example:
exports capability { Takedown }

capability Edge = EdgeCache

capability Takedown {   // ✗ exported, but its provider purges through `Edge`
    fn take(path: String) -> Effect[Bool]
}

provides Takedown = Purging given Edge {
    fn take(path: String) -> Effect[Bool] {
        Edge.purge([path])
    }
}

service operator from http {
    on POST("/purge/:hex") (hex: String) -> Effect[HttpResult[Bool]] by v: Visitor given Edge {   // ✓ purge from a service handler
        let purged <- Edge.purge(["/dl/\(hex)"])
        Ok(purged)
    }
}
